    Fixture f;const auto id=f.start();auto* start=f.state.starts.find(id);start->session_id="original_session";start->dialogue_id="recipient_dialogue";start->node_id="say";start->context={"recipient_place","recipient","recipient_role"};
    const auto action_id=start->action_id;ActionCoreView action{action_id,task_message_return_collect_command,"carrier",{"carrier"},0,1};ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action=action;need(f.common.apply_action(insert).ok,"original active action inserted");
    need(!player_plan_message_return_continuation(f.common,f.state,action),"unbound start cannot be continued");const auto& committed=f.commit("carrier",task_message_return_collect_command,1,ActionStarted{action_id});auto x=f.context();need(bind_task_message_return_results(f.common,f.state,x,{id},"carrier",1,committed,0).ok,"actual cached start binds");
    need(player_plan_message_return_continuation(f.common,f.state,action),"exact original one-halfday action continued");auto changed=action;changed.actor_id="clock_actor";need(!player_plan_message_return_continuation(f.common,f.state,changed),"different participant rejected");changed=action;changed.remaining_ticks=2;need(!player_plan_message_return_continuation(f.common,f.state,changed),"invented duration rejected");changed=action;changed.start_tick=1;need(!player_plan_message_return_continuation(f.common,f.state,changed),"invented start rejected");changed=action;changed.kind="report_offer";need(!player_plan_message_return_continuation(f.common,f.state,changed),"original report is not a collect action");
    auto source=query_task_message_return_action(f.common,f.state,"carrier",action_id);need(source.ok&&source.value,"active source exists");InteractionSession say;say.id=start->session_id;say.actor_id="carrier";say.dialogue_id=start->dialogue_id;say.node_id=start->node_id;say.phase="say";say.context=start->context;need(task_message_return_continuation_meeting_matches(*source.value,say),"exact original SAY exempted");auto other=say;other.id="another";need(!task_message_return_continuation_meeting_matches(*source.value,other),"new session stops continuation");other=say;other.node_id="another";need(!task_message_return_continuation_meeting_matches(*source.value,other),"new choice stops continuation");other=say;other.context.kind="encounter";need(!task_message_return_continuation_meeting_matches(*source.value,other),"encounter does not borrow SAY");other=say;other.pending_action_id="other";need(!task_message_return_continuation_meeting_matches(*source.value,other),"pending command stops continuation");
    auto erased=insert;erased.kind=ActionMutation::Kind::erase;need(f.common.apply_action(erased).ok,"original action release");f.common.state().identity.tick=1;auto lot=f.common.next_id("lot"),fact=f.common.next_id(task_message_return_collected_kind);need(lot.ok&&fact.ok&&f.common.append_fact({fact.value,task_message_return_collected_kind,task_message_return_module}).ok,"actual IDs and collection source");TaskMessageReturnCollection collection;collection.fact_id=fact.value;collection.start_fact_id=id;collection.task_id=start->task_id;collection.action_id=action_id;collection.reply_lot_id=lot.value;collection.tick=1;collection.success=true;f.state.collections.insert(fact.value,collection);
    TaskEffect effect;effect.task_id=collection.task_id;ActionCompletion completion;completion.task=effect;AdvanceDetails advance;advance.completed_actions.insert(action_id,completion);const auto& result=f.commit("carrier","advance",2,advance);auto after=f.context();need(bind_task_message_return_results(f.common,f.state,after,{fact.value},"carrier",2,result,0).ok,"actual Advance binds completion");auto done=query_task_message_return_completion(f.common,f.state,"carrier",action_id,*result.details,1,result.result_id);need(done.ok&&done.value&&done.value->status=="collected","original actual completion read");need(!player_plan_message_return_continuation(f.common,f.state,action),"completed action cannot reopen");need(!task_message_return_continuation_meeting_matches(*done.value,say),"finished source no longer exempts SAY");need(!query_task_message_return_completion(f.common,f.state,"clock_actor",action_id,*result.details,1,result.result_id).ok,"wrong carrier cannot borrow completion");need(!query_task_message_return_completion(f.common,f.state,"carrier",action_id,*result.details,1,committed.result_id).ok,"start result cannot replace completion");auto mixed=advance;mixed.completed_actions.find(action_id)->code="TaskMessageReturnCollected";need(!query_task_message_return_completion(f.common,f.state,"carrier",action_id,{mixed,{}},1,result.result_id).ok,"collect cannot invent generic completion code");mixed=advance;mixed.completed_actions.find(action_id)->military_field_order={"mixed"};need(!query_task_message_return_completion(f.common,f.state,"carrier",action_id,{mixed,{}},1,result.result_id).ok,"mixed domain receipt rejected");
    PlayerPlanState plan;plan.current=PlayerPlan{"plan","carrier",0,{},"",{}};PlayerPlanStep step;step.id="step";step.data=PlayerPlanContinue{action_id};step.source={PlayerPlanSourceKind::existing_action,action_id,0};plan.current->steps.push_back(step);need(player_plan_record_started(plan,"plan","step",action_id,result.result_id,1).ok,"Continue records first actual Advance");need(player_plan_record_completed(plan,"plan","step",action_id,result.result_id,1,true,{}).ok,"success preserves original empty TaskEffect code");need(plan.current->steps.front().phase==PlayerPlanStepPhase::completed&&plan.current->steps.front().stop_reason.empty(),"plan successful receipt shape unchanged");
