    f.state.collections.find(fact.value)->success=false;f.state.collections.find(fact.value)->reply_lot_id.clear();f.state.collections.find(fact.value)->reason="TaskMessageReturnMeetingChanged";auto failed=advance;failed.completed_actions.find(action_id)->task->success=false;failed.completed_actions.find(action_id)->task->code="TaskMessageReturnMeetingChanged";auto stopped=query_task_message_return_completion(f.common,f.state,"carrier",action_id,{failed,{}},1,result.result_id);need(stopped.ok&&stopped.value&&stopped.value->status=="interrupted","real failure shape retained");failed.completed_actions.find(action_id)->task->code.reset();need(!query_task_message_return_completion(f.common,f.state,"carrier",action_id,{failed,{}},1,result.result_id).ok,"removed failure code rejected");
    std::cout<<checks<<" Plan return source/receipt boundary checks; Task resources and World deferred\n";return 0;
